<script setup lang="ts">
import { useApi } from '../../../api/client'
import { apiError } from '../../../utils/apiError'
import { formatChangeReport, relativeTime } from '../../../utils/site'
const api = useApi(); const route = useRoute(); const toast = useToast(); const id = String(route.params.id); const page = ref(1); const size = 20
const { data: site, error, refresh } = await useAsyncData(`site-${id}`, async () => { const r = await api.GET('/sites/{site_id}', { params: { path: { site_id: id } } }); if (!r.data) throw new Error(apiError(r.error)); return r.data })
const { data: history, error: historyError } = await useAsyncData(`site-history-${id}`, async () => { const r = await api.GET('/sites/{site_id}/crawls', { params: { path: { site_id: id }, query: { offset: (page.value - 1) * size, limit: size } } }); if (!r.data) throw new Error(apiError(r.error)); return r.data }, { watch: [page] })
async function check() { const r = await api.POST('/sites/{site_id}/check', { params: { path: { site_id: id } } }); toast.add({ title: r.data ? 'Check started' : r.response.status === 409 ? 'A check is already running' : 'Could not start check', color: r.data ? 'success' : 'error' }) }
async function toggle() { if (!site.value) return; const r = await api.PATCH('/sites/{site_id}', { params: { path: { site_id: id } }, body: { enabled: !site.value.enabled } }); if (!r.data) toast.add({ title: 'Could not update site', description: apiError(r.error), color: 'error' }); else await refresh() }
async function remove() { if (!confirm('Delete this site?')) return; const r = await api.DELETE('/sites/{site_id}', { params: { path: { site_id: id } } }); if (!r.response.ok) toast.add({ title: 'Could not delete site', description: apiError(r.error), color: 'error' }); else await navigateTo('/sites') }
</script>
<template><div><Crumbs class="mb-4" :items="[{ label: 'Sites', to: '/sites' }]" /><UAlert v-if="error" color="error" :description="error.message" /><template v-else-if="site"><PageHeader :title="site.name || site.domain" :description="site.domain"><template #actions><UButton :to="`/sites/${id}/edit`" variant="outline">Edit</UButton><UButton @click="check">Check now</UButton><UButton color="neutral" variant="outline" @click="toggle">{{ site.enabled ? 'Disable' : 'Enable' }}</UButton><UTooltip :text="historyError ? 'Unable to determine whether this site has crawls' : 'Sites with crawls cannot be deleted; disable them instead'" :disabled="!!history && !history.total"><span><UButton color="error" variant="outline" :disabled="!history || history.total > 0" @click="remove">Delete</UButton></span></UTooltip></template></PageHeader>
<section class="space-y-2"><h2 class="font-bold">Settings</h2><p>Language: {{ site.language }} · {{ site.enabled ? 'Enabled' : 'Disabled' }} · Every {{ site.check_every_minutes }} min · Daily cap: {{ site.daily_cap }}</p><p>Articles per day: {{ site.per_day }} · Minimum interval: {{ site.min_interval_seconds }} seconds · Max parallel: {{ site.max_parallel }}</p><p>Sitemaps: {{ site.sitemaps?.join(', ') || 'Automatic' }}</p><p>Feeds: {{ site.feeds?.join(', ') || 'Automatic' }}</p></section>
<section class="mt-8 space-y-3"><h2 class="font-bold">Check history</h2><UAlert v-if="historyError" color="error" :description="historyError.message" /><p v-else-if="!history?.items.length">No checks yet.</p><table v-else class="w-full text-left text-sm"><thead><tr><th>Date</th><th>Status</th><th>Trigger</th><th>Changes</th></tr></thead><tbody><tr v-for="crawl in history.items" :key="crawl.id"><td class="py-3"><NuxtLink class="text-primary" :to="`/crawls/${crawl.id}`">{{ relativeTime(crawl.created_at) }}</NuxtLink></td><td><StatusBadge :status="crawl.status" /></td><td>{{ crawl.trigger }}</td><td>{{ formatChangeReport(crawl.counters) }}</td></tr></tbody></table><UPagination v-if="history && history.total > size" v-model:page="page" :items-per-page="size" :total="history.total" /></section></template></div></template>
